script:
(function () {
  'use strict';
  // Biweekly half-payments on an auto loan vs the normal monthly payment, with dates.
  //   Monthly payment M = L x i / (1 - (1 + i)^-n), i = APR / 12 (M = L / n at 0%).
  //   Most auto loans charge simple interest that accrues daily, so both plans are simulated day by day:
  //   interest = balance x APR / 365 x days since the last payment; each payment covers that interest
  //   first and the rest reduces the balance (the last monthly payment is adjusted to clear the balance). The loan is assumed to start one month before the first
  //   payment. Monthly plan: M on the same day each month. Biweekly plan: M / 2 (+ any extra) every
  //   14 days from the first payment date, each payment credited when made (26 a year, which works out
  //   to about one extra monthly payment a year). Fees apply to the biweekly plan only.
  // Verified in Node (scratchpad tests/auto5): $30,000 at 7% for 60 months = $594.04/mo (closed form);
  //   the daily-interest monthly schedule ends on the 60th payment with total interest $5,644.70, within
  //   0.1% of the closed-form $5,642.16; the biweekly plan takes 119 payments, matching
  //   1 + ceil(-ln(1 - B1 j / P) / ln(1 + j)) with j = 0.07 x 14 / 365, P = M / 2 and B1 the balance after
  //   the first (one-month) period; at 0% both plans pay exactly $30,000 and biweekly ends sooner;
  //   dates clamp at month ends (Jan 31 -> Feb 28) and handle Feb 29; invalid dates (2026-02-30), blank,
  //   zero or negative input show an error with no NaN or Infinity on the page.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var longDate = new Intl.DateTimeFormat('en-US', { month: 'long', day: 'numeric', year: 'numeric', timeZone: 'UTC' });
  var DAY = 86400000;

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function parseDate(s) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s).trim());
    if (!m) return null;
    var y = +m[1], mo = +m[2] - 1, d = +m[3];
    if (y < 1990 || y > 2100) return null;
    var t = Date.UTC(y, mo, d), dt = new Date(t);
    if (dt.getUTCMonth() !== mo || dt.getUTCDate() !== d) return null;
    return t;
  }

  // Same day of the month k months later, clamped to the month's last day.
  function addMonths(t, k, day) {
    var d = new Date(t), y = d.getUTCFullYear(), m = d.getUTCMonth() + k;
    var last = new Date(Date.UTC(y, m + 1, 0)).getUTCDate();
    return Date.UTC(y, m, Math.min(day, last));
  }

  function monthlyPayment(principal, annualRate, months) {
    if (months <= 0 || principal <= 0) return 0;
    var i = annualRate / 12;
    if (i === 0) return principal / months;
    return principal * i / (1 - Math.pow(1 + i, -months));
  }

  // dates(k) gives the k-th payment date (k = 0, 1, ...). Returns payments, interest, payoff date and
  // the balance at each anniversary of the loan start.
  function simulate(loan, rate, startT, dates, pay, day, finalK) {
    var bal = loan, prev = startT, interest = 0, k = 0, yearEnd = [], nextYear = addMonths(startT, 12, day);
    var yearIdx = 1, last = startT;
    while (bal > 0.005 && k < 2000) {
      var t = dates(k);
      while (t > nextYear) { yearEnd.push(bal); yearIdx++; nextYear = addMonths(startT, 12 * yearIdx, day); }
      var intr = bal * rate / 365 * Math.round((t - prev) / DAY);
      var p = k === finalK ? bal + intr : Math.min(pay, bal + intr);
      if (p <= intr && p < bal + intr) return null;
      bal = bal + intr - p;
      if (bal < 0.005) bal = 0;
      interest += intr;
      prev = t; last = t; k++;
    }
    yearEnd.push(bal);
    return { payments: k, interest: interest, payoff: last, yearEnd: yearEnd };
  }

  function todayISO() {
    var d = new Date();
    var p = function (n) { return (n < 10 ? '0' : '') + n; };
    return d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate());
  }

  function clearResults() {
    ['baBiPay', 'baInterestSaved', 'baTimeSaved', 'baPayoff', 'baMonthlyPay', 'baMonthlyPayoff', 'baMonthlyInt',
     'baBiInt', 'baCount', 'baFees', 'baNet'].forEach(function (id) { setText(id, '–'); });
    el('baYears').innerHTML = '';
  }

  function update() {
    var amount = read('baAmount'), rate = read('baRate'), term = read('baTerm'), extra = read('baExtra', true),
        setup = read('baSetupFee', true), perFee = read('baPerFee', true), firstT = parseDate(el('baFirst').value);
    var error = el('baError'), msg = '';
    if (isNaN(amount) || amount <= 0) msg = 'Enter a loan amount greater than $0.';
    else if (isNaN(rate) || rate < 0 || rate > 40) msg = 'Enter an interest rate from 0% to 40%.';
    else if (isNaN(term) || term < 6 || term > 120 || term % 1 !== 0) msg = 'Enter a loan term of 6 to 120 whole months.';
    else if (firstT === null) msg = 'Enter a valid first payment date.';
    else if ([extra, setup, perFee].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Amounts cannot be negative.';
    if (msg) { error.hidden = false; error.textContent = msg; clearResults(); return; }

    var r = rate / 100, M = monthlyPayment(amount, r, term), day = new Date(firstT).getUTCDate();
    var startT = addMonths(firstT, -1, day);
    var mo = simulate(amount, r, startT, function (k) { return addMonths(firstT, k, day); }, M, day, term - 1);
    var bi = simulate(amount, r, startT, function (k) { return firstT + 14 * k * DAY; }, M / 2 + extra, day, -1);
    if (!mo || !bi) { error.hidden = false; error.textContent = 'The payment is too small to cover the interest. Check the rate and term.'; clearResults(); return; }
    error.hidden = true;
    error.textContent = '';

    var fees = setup + perFee * bi.payments, saved = mo.interest - bi.interest;
    var daysSooner = Math.round((mo.payoff - bi.payoff) / DAY), monthsSooner = Math.round(daysSooner / 30.4375);
    setText('baBiPay', money.format(M / 2 + extra));
    setText('baInterestSaved', money.format(Math.max(0, saved)));
    setText('baTimeSaved', daysSooner <= 0 ? 'No change' : monthsSooner >= 1 ? 'About ' + monthsSooner + (monthsSooner === 1 ? ' month' : ' months') : daysSooner + (daysSooner === 1 ? ' day' : ' days'));
    setText('baPayoff', longDate.format(new Date(bi.payoff)));
    setText('baMonthlyPay', money.format(M));
    setText('baMonthlyPayoff', longDate.format(new Date(mo.payoff)));
    setText('baMonthlyInt', money.format(mo.interest));
    setText('baBiInt', money.format(bi.interest));
    setText('baCount', mo.payments + ' monthly vs ' + bi.payments + ' biweekly');
    setText('baFees', money.format(fees));
    var net = saved - fees;
    setText('baNet', (net < 0 ? '−' : '') + money.format(Math.abs(net)));

    var n = Math.max(mo.yearEnd.length, bi.yearEnd.length), html = [];
    for (var y = 0; y < n; y++) {
      var a = y < mo.yearEnd.length ? mo.yearEnd[y] : 0, b = y < bi.yearEnd.length ? bi.yearEnd[y] : 0;
      html.push('<tr><td>' + (y + 1) + '</td><td>' + money0.format(a) + '</td><td>' + money0.format(b) + '</td><td>' +
        money0.format(Math.max(0, a - b)) + '</td></tr>');
    }
    el('baYears').innerHTML = html.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('baForm');
    if (!form) return;
    if (!String(el('baFirst').value).trim()) el('baFirst').value = todayISO();
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
